\begin{problem}[Ringel (1967)]
Let $n \geq 3$ be an odd integer, and let $F$ be any 2-regular graph on $n$ vertices. Does the complete graph $K_n$ have an $F$-decomposition?
\end{problem}

\begin{conjecture}[Glock, K\"uhn, and Osthus~\cite{GlockKuhnOsthus2021Survey}]\label{conj:gen_oberwolfach}
For any $\varepsilon > 0$, there exist integers $L$ and $n_0$ such that the following holds for all integers $n \geq n_0$.
Let $G$ be a $D$-regular graph on $n$ vertices with $D \in 2 \mathbb{N}$, and let $F$ be a 2-regular graph on $n$ vertices. 
\begin{enumerate}[label=\textup{(\roman*)}]
    \item If $D \geq (3/4 + \varepsilon)n$, then $G$ has an $F$-decomposition.

    \item If $D \geq (2/3 + \varepsilon)n$ and all cycles in $F$ have even length, then $G$ has an $F$-decomposition.

    \item If $D \geq (1/2 + \varepsilon)n$ and all cycles in $F$ have even length at least 6, then $G$ has an $F$-decomposition.

    \item If $D \geq (1/2 + \varepsilon)n$ and all cycles in $F$ have length at least $L$, then $G$ has an $F$-decomposition.
\end{enumerate}
\end{conjecture}

\begin{corollary}\label{thm:main:resolution}
For every integer $r\ge3$,
$\delta^{\rm res}_{C_r}=\delta_{C_r}=\tau_r$.
\end{corollary}

\begin{theorem}\label{doLpart:thm:main}
Let $k\ge2$ and $n\ge1$ be integers, and put $\ell=2k$.
Let $G$ be a locally balanced $\ell$-cyclic graph with specified classes
$V_0,\ldots,V_{\ell-1}$ of size $n$. Suppose
\begin{equation}
 \label{doLpart:eq:main-threshold}
 \delta_{\rm cyc}(G)\ge q_\ell n = \frac{k}{2k-1}n.
\end{equation}
Then there is a fractional part-respecting $C_\ell$-decomposition
$\omega:\mathcal C^{\rm part}_\ell(G)\to\mathbb R_{\ge0}$ of $G$.
\end{theorem}

\begin{theorem}[Hall's theorem]
\label{thm:prelim:hall}
Let $B$ be a bipartite graph with parts $X,Y$.
Then $B$ has a matching $M$ with $X\subseteq V(M)$ if and only if
$|\Gamma_B(S)|\ge|S|$ for every $S\subseteq X$.
\end{theorem}

\begin{definition}[The large-cut condition]\label{def:pr:cut}
Let $0\le\delta<1/4$ and $h>0$.
Let $J$ be a bipartite graph with parts $A_1,A_2$ of sizes $a_1,a_2>0$.
We say that $J$ satisfies the $(\delta,h)$ large-cut condition if
\begin{equation}
 e_J(X,Y)\ge h\min\{a_2|X|,a_1|Y|\}
 \quad\text{whenever } |X|/a_1+|Y|/a_2>1-2\delta,
 \label{eq:cuts:large}
\end{equation}
for all $X\subseteq A_1$ and $Y\subseteq A_2$.
For a directed multigraph $R$, its bipartite representation is
$D_R=(V(R)^+,V(R)^-;E_R)$, on two labelled copies of $V(R)$.
Its edges are indexed by the arcs of $R$, with the bijection
\begin{equation}
 \beta_R:E(R)\longrightarrow E_R,\qquad
 \beta_R(e)=x^+y^-\quad\text{if $e$ has tail $x$ and head $y$}.
 \label{eq:digraph:bipartite-representation}
\end{equation}
Parallel arcs give distinct indexed edges of $D_R$.
A large-cut condition on $R$ means $D_R$ satisfies \eqref{eq:cuts:large}.
\end{definition}

\begin{theorem}[Brouwer's fixed-point theorem]
\label{thm:prelim:brouwer}
Let $E$ be a finite-dimensional real vector space,
let $K\subseteq E$ be nonempty, compact and convex, and let $T:K\to K$ be continuous.
Then there is $x\in K$ with $T(x)=x$.
\end{theorem}

\begin{proposition}[Regular lower-bound examples]
\label{prop:four:lower}
Let $r\ge3$ be an integer. Then
$\delta_{C_r}\ge\tau_r$ and $\delta^{\rm res}_{C_r}\ge\tau_r$.
In particular, $\delta_{C_r}\ge\nu_r\ge\mu_r\ge1/2$.
\end{proposition}

\begin{localclaim}\label{clm:threshold:divisible-partition}
For all sufficiently large $n$, there is a partition
\[
 E(G)=J_1\mathbin{\dot\cup}\cdots\mathbin{\dot\cup}J_R
\]
such that, for every $i\in[R]$ and $v\in V(G)$,
\begin{align}
 d_{J_i}(v)&\equiv d_G(v)\pmod2, \label{eq:four:2reg-parity}\\
 |J_i|&\equiv e(G)\pmod h, \label{eq:four:2reg-size}\\
 d_{J_i}(v)&\le \frac{d_G(v)}R+\xi n. \label{eq:four:2reg-degree}
\end{align}
\end{localclaim}

\begin{theorem}[Weights on marked cycles from degree and cut bounds]
\label{thm:capacity:marked-numerical}
Fix $0<\alpha<1/4$ and $0<p_{\rm rim}<1/2$.
There is $c_0=c_0(\alpha,p_{\rm rim})$ such that for every even
$c\ge c_0$ there are $\varepsilon,\kappa,a,A>0$ as follows.
For every integer $b\ge2$ there is $n_0\in\mathbb N$ such that the
following holds for every integer $n\ge n_0$ and every
$p\in[p_{\rm rim},1/2)$.

Let $V$ have size $n$, let $\pi$ be a permutation of $V$, and let
$R^0,R^K$ be digraphs on $V$.
Put $R=R^0\mathbin{\dot\cup}R^K$. Its physical image map
$\operatorname{phys}:E(R)\to2^V$ is
\[
 \operatorname{phys}(x\to y)=\{x,y\}\quad(x\to y\in R^0),\qquad
 \operatorname{phys}(x\to y)=\{x,\pi(y)\}\quad(x\to y\in R^K).
\]
Assume that $\operatorname{phys}$ is injective, $|\operatorname{phys}(e)|=2$ for $e\in E(R)$,
and $\operatorname{dist}_\pi(x,y)>b$ for every arc $x\to y$ of $R$.
For some real $D\in[n/2,2n]$, suppose
\begin{equation}
 |d^\pm_{R^0}(v)-pD|\le\varepsilon n,\qquad
 |d^\pm_{R^K}(v)-pD/(c-1)|\le\varepsilon n\quad(v\in V),
 \label{eq:capacity:degree}
\end{equation}
\begin{equation}
 |N^+_{R^0}(x)\cap N^-_{R^0}(y)|\ge\alpha p^2n
       \quad(x,y\in V,\ x\ne y).
 \label{eq:capacity:paths}
\end{equation}
Put
\begin{equation}
 \delta_c=\min\{\alpha/16,p/128\},\qquad h_c=\alpha p/16.
 \label{eq:capacity:cuts}
\end{equation}
For $J_0=D_{R^0}$ on $(V^+,V^-)$, suppose
\begin{equation}
 e_{J_0}(X,Y)\ge h_c n\min\{|X|,|Y|\}
 \quad\text{if }|X|+|Y|>(1-2\delta_c)n
 \label{eq:capacity:large-cut}
\end{equation}
for all $X\subseteq V^+$ and $Y\subseteq V^-$.
Let $w:E(R)\to\mathbb R_{\ge0}$ satisfy
$\|w-\mathbf1\|_\infty\le\kappa$ and
\begin{equation}
 \sum_{e\text{ leaves }v}w(e)=\sum_{e\text{ enters }v}w(e)\quad(v\in V),
 \qquad
 \sum_{e\in E(R^0)}w(e)=(c-1)\sum_{e\in E(R^K)}w(e).
 \tag{M2}\label{eq:capacity:balance}
\end{equation}
Let $\mathcal C$ consist of the directed $c$-cycles in $R$ with exactly
one type-$K$ arc, a $(b,\pi)$-separated vertex set and $c$ distinct
physical images. Then there exists $\lambda:\mathcal C\to\mathbb R_{\ge0}$ such that
\begin{equation}
 \sum_{C\ni e}\lambda(C)=w(e)\quad(e\in E(R)),\qquad
 an^{2-c}\le\lambda(C)\le An^{2-c}\quad(C\in\mathcal C).
 \tag{M3}\label{eq:capacity:cycle-weights}
\end{equation}
\end{theorem}

\begin{localclaim}\label{clm:capacity:position-splitting}
There are positive functions $d_0,\ldots,d_{c-1}$ on $V$ and
$f_0,\ldots,f_{c-2}$ on $E(R^0)$ such that
\[
\begin{gathered}
 d_0(v)=\sum_{x\to v\in R^K}w(xv),\qquad
 d_{c-1}(v)=\sum_{v\to x\in R^K}w(vx)\quad(v\in V),\\
 \sum_{v\in V}d_j(v)=M\quad(0\le j\le c-1),
\end{gathered}
\]
\begin{equation}
\begin{aligned}
 \sum_{j=0}^{c-2}f_j(e)&=w(e)&& (e\in E(R^0)),\\
 \sum_{v\to x\in R^0}f_j(vx)&=d_j(v),\qquad
 \sum_{x\to v\in R^0}f_j(xv)=d_{j+1}(v)
       && (v\in V,\ 0\le j\le c-2),
\end{aligned}
\label{eq:capacity:position-sums}
\end{equation}
and
\begin{equation}
\begin{gathered}
 \frac1{2(c-1)}\le f_j(e)\le\frac2{c-1}
       \quad(e\in E(R^0),\ 0\le j\le c-2),\\
 0.9q\le d_j(v)\le1.1q
       \quad(v\in V,\ 0\le j\le c-1).
\end{gathered}
 \tag{M8}\label{eq:capacity:position-bounds}
\end{equation}
\end{localclaim}

\begin{definition}[Ordinary relative typicality]\label{def:pr:rt1}
Let $h\ge0$ be an integer and $\varepsilon\ge0$.
The row property $\mathrm{RT}_V^{\rm ord}(\varepsilon,h)$ on $A$ is
\begin{equation}
 |N_V^{\rm ord}(A;S,T,J)-\mu_V^{\rm ord}(A;S,T,J)|\le\varepsilon|A|
 \quad(|S|+|T|+|J|\le h).
 \label{eq:cn:ordinary-V}
\end{equation}
The index property $\mathrm{RT}_U^{\rm ord}(\varepsilon,h)$ on $B$ is
\begin{equation}
 |N_U^{\rm ord}(B;S)-\mu_U^{\rm ord}(B;S)|\le\varepsilon|B|
 \quad(|S|\le h,\ E(F[S])=\varnothing).
 \label{eq:cn:ordinary-U}
\end{equation}
When both hold, $(R,H)$ is $(\varepsilon,h)$-typical relative to
$(P,P_{\rm el},F;q,s)$ on $(A,B)$, with $S,T\subseteq X$ and $J\subseteq Y$ as above.
The two properties may also be imposed separately, with different values of $h$.
\end{definition}

\begin{definition}[Marked relative typicality]\label{def:pr:marked-typicality}
Let $h\ge0$ be an integer and $\varepsilon\ge0$.
The row property $\mathrm{RT}_V^{\rm mark}(\varepsilon,h)$ on $A$ requires,
for every row pattern $i$ with
$k_0+k_K+\sum_{\tau,e}|T_\tau^e|+|J_0|+|J_K|\le h$,
\begin{equation}
 |N_V^{\rm mark}(A;i)-\mu_V^{\rm mark}(A;i)|\le\varepsilon|A|.
 \label{eq:cn:marked-V}
\end{equation}
The index property $\mathrm{RT}_U^{\rm mark}(\varepsilon,h)$ on $B$ is
\begin{equation}
 |N_U^{\rm mark}(B;S_0,S_K)-\mu_U^{\rm mark}(B;S_0,S_K)|\le\varepsilon|B|
 \quad(|S_0|+|S_K|\le h).
 \label{eq:cn:marked-U}
\end{equation}
When both hold, $\mathcal Q$ is $(\varepsilon,h)$-typical relative to
$(P,E_0,E_K,F,\pi;p_0,p_K,s_0,s_K)$ on $(A,B)$, with the sets
$S_\tau^e,T_\tau^e,S_0,S_K\subseteq X$ and $J_0,J_K\subseteq Y$ as above.
Either property may be imposed separately, with its own value of $h$.
The right-hand side of \eqref{eq:cn:marked-V} is $\varepsilon|A|$,
even if $A_i^\circ$ is empty.
\end{definition}

\begin{definition}[Ordinary completion host]
\label{def:completion:ordinary-host}
The eligible ordinary edges are
\begin{equation}
 \mathfrak E^{\rm ord}
 =\{\{x,y\}\in E(P):\operatorname{dist}_\pi(x,y)>3d\}
       \mathbin{\dot\cup}\{\{v,u\}:v\in V,\ u\in U\}.
 \label{eq:completion:ordinary-potential-edges}
\end{equation}
An \emph{ordinary completion host} is $\mathcal Q=(V,U,R,H)$,
where $R$ is a graph on $V$, $H$ is bipartite on $V,U$, and
$E(R)\mathbin{\dot\cup}E(H)\subseteq\mathfrak E^{\rm ord}$.
\end{definition}

\begin{definition}[Marked completion host]
\label{def:completion:marked-host}
The eligible marked occurrences are
\begin{equation}
\begin{split}
 \mathfrak E^{\rm mark}
 &=\{(x,y,j):x,y\in V,\ j\in\{0,K\},\
       \operatorname{dist}_\pi(x,y)>3d,\ \operatorname{phys}(x,y,j)\in E(P)\}\\
 &\qquad\mathbin{\dot\cup}\{(v,u,j):v\in V,\ u\in U,\ j\in\{0,K\}\}.
\end{split}
\label{eq:completion:marked-potential-edges}
\end{equation}
Here $\operatorname{phys}(x,y,0)=\{x,y\}$ and
$\operatorname{phys}(x,y,K)=\{x,\pi(y)\}$.
A \emph{marked completion host} is a tuple
$\mathcal Q=(V,U,R^0,R^K,H^0,H^K)$, where $R^0,R^K$ are digraphs
on $V$ and $H^0,H^K$ are bipartite on $V,U$. For each $j\in\{0,K\}$,
require $(x,y,j)\in\mathfrak E^{\rm mark}$ for every $x\to y\in E(R^j)$
and $(v,u,j)\in\mathfrak E^{\rm mark}$ for every $vu\in E(H^j)$. Moreover,
$E(H^0)\cap E(H^K)=\varnothing$ and
\begin{equation}
 N_{H^0}(u)\cap\pi(N_{H^K}(u))=\varnothing\quad(u\in U).
 \label{eq:completion:successor-disjointness}
\end{equation}
Put $R=R^0\dot\cup R^K$ and $H=H^0\dot\cup H^K$, retaining types.
Such a host is \emph{physically injective} if
$e\mapsto\operatorname{phys}(e)$ is injective on the arc occurrences of $R$.
\end{definition}

\begin{theorem}[Exact marked wheel weights from numerical estimates]
\label{thm:weights:marked-numerical}
Fix $\alpha,p_{\rm rim},p_*,\beta,b_-,b_+,\omega_W>0$, with
$\alpha<1/4$, $p_{\rm rim}<1/2$ and $b_-\le b_+$.
Let $c\ge\max\{8,c_0(\alpha,p_{\rm rim})\}$ be even, where $c_0$ is from
Theorem~\ref{thm:capacity:marked-numerical}. There are
$\varepsilon_*,\eta_*,\delta_*,A>0$ such that for every integer $b\ge2$
there is $n_0\in\mathbb N$ for which the following holds for every
integer $n\ge n_0$ and every $p\in[p_{\rm rim},1/2)$.

Let $\mathcal Q=(R^0,R^K,H^0,H^K)$ be a typed graph on $(V,W,\pi)$,
where $|V|=n$ and $\omega_Wn\le|W|\le n$, with disjoint spoke types
and injective rim physical map \eqref{eq:physical:image-map}.
Let $\varsigma_0,\varsigma_K\in[p_*,1]$, $\delta\ge0$, $D_{\rm exc}\in\mathbb Z_{\ge0}$,
and put $R=R^0\dot\cup R^K$, $H=H^0\dot\cup H^K$ and
$\mathcal W(\mathcal Q)=\mathcal W_c^K(\mathcal Q;b,\pi)$.
Assume that $(\mathcal Q,(\varsigma_j))$ has $(b,\pi)$-separated marked
host estimates at degree $D\in[n/2,2n]$ and rim density $p$, with
errors $(\varepsilon_*,\delta)$, extension coefficient $\beta$,
rim bounds $(\alpha p^2,\delta_c,h_c)$ and exception bound $D_{\rm exc}$.
Let $\omega_0:\mathcal W(\mathcal Q)\to\mathbb R_{\ge0}$ satisfy
\begin{equation}
\label{eq:marked:initial-weights}
 b_-n^{1-c}\le\omega_0(W')\le b_+n^{1-c}
 \quad(W'\in\mathcal W(\mathcal Q)),\qquad
 |L_{\omega_0}(e)-1|\le\eta_*\quad(e\in\mathcal E(R,H)).
\end{equation}
Here $\delta_c,h_c$ are given by \eqref{eq:capacity:cuts}. Suppose also
\begin{equation}
 \delta+D_{\rm exc}/n+1/|W|\le\delta_*,
 \label{eq:marked:spoke-budget}
\end{equation}
and, for every $v\in V$ and $u\in W$,
\begin{equation}
 d_R^+(v)=d_R^-(v)=d_H(v),\quad d_{R^K}^-(v)=d_{H^K}(v),\quad
 d_{H^0}(u)=(c-1)d_{H^K}(u).
 \label{eq:marked:exact-degrees}
\end{equation}
Then there exists $\omega:\mathcal W(\mathcal Q)\to\mathbb R_{\ge0}$ such that
\begin{equation}
 L_\omega(e)=1\quad(e\in\mathcal E(R,H)),\qquad
 \frac{b_-}{2}n^{1-c}\le\omega(W')\le An^{1-c}
                 \quad(W'\in\mathcal W(\mathcal Q)).
 \label{eq:marked:exact-weights}
\end{equation}
\end{theorem}

\begin{definition}[Marked endpoint assignment graphs]
\label{def:endpoints:assignment-graphs}
Let $V,U$ be disjoint finite sets, let $P$ be a simple graph on $V$,
let $\pi$ be a permutation of $V$, and let $d\ge0$.
Define the potential arc sets by
\[
\begin{aligned}
 E(\overline R^0)&=\{v\to w:vw\in E(P),\ \operatorname{dist}_\pi(v,w)>3d\},\\
 E(\overline R^K)&=\{v\to w:v\pi(w)\in E(P),\ \operatorname{dist}_\pi(v,w)>3d\}.
\end{aligned}
\]
An arc $v\to w$ of type $K$ has auxiliary head $w$ and physical
edge $\{v,\pi(w)\}$. Let
$\mathcal Q=(R^0,R^K,H^0,H^K)$ have $R^j\subseteq\overline R^j$
and spoke graphs $H^j$ on $(V,U)$.
Fix $A\subseteq V$ with $\pi(A)=A$, $B\subseteq U$, and $x\in V$.
For $j\in\{0,K\}$ put
\[
\begin{aligned}
 \overline A_j(x)&=\{v\to x\in E(\overline R^j):v\in A\},&
 A_j(x)&=\overline A_j(x)\cap E(R^j),\\
 \overline X_j(x)&=\{x\to v\in E(\overline R^j):v\in A\},&
 X_j(x)&=\overline X_j(x)\cap E(R^j),\\
 Y_j(x)&=\{u\in B:xu\in E(H^j)\}.&&
\end{aligned}
\]
All row elements are arc indices, and indices with the same endpoint
label remain distinct. The five pairs of actual parts $(P_{x,i},Q_{x,i})$
and the larger row domains $\overline P_{x,i}$ are given below.
For target spoke densities $s,t\in[0,1]$, the last two columns give
the density $r_i$ at $x$ and the density $z_i$ at the other label.
\begin{equation}
\begin{array}{c|c|c|c|c|c}
 i&P_{x,i}&Q_{x,i}&\overline P_{x,i}&r_i&z_i\\\hline
 1&A_K(x)&Y_K(x)&\overline A_K(x)&t&s\\
 2&A_0(x)&Y_0(x)&\overline A_0(x)&s&s\\
 3&X_K(x)&Y_0(x)&\overline X_K(x)&s&t\\
 4&X_0(x)&Y_0(x)&\overline X_0(x)&s&s\\
 5&X_0(x)&Y_K(x)&\overline X_0(x)&t&s
\end{array}
\label{eq:endpoints:index-table}
\end{equation}
Let $\ell_{x,i}:\overline P_{x,i}\to A$ be the tail map for $i=1,2$
and the auxiliary-head map for $i=3,4,5$; restrict it to $P_{x,i}$
on actual rows. Put $\tau_3=K$ and $\tau_i=0$ for $i\ne3$.
The potential bipartite graph $\overline D_{x,i}$ has parts
$(\overline P_{x,i},B)$, with
\begin{equation}
 a'u\in E(\overline D_{x,i})\quad\Longleftrightarrow\quad
 \ell_{x,i}(a')u\in E(H^{\tau_i})
 \quad(a'\in\overline P_{x,i},\ u\in B).
 \label{eq:endpoints:potential-graphs}
\end{equation}
The \emph{marked endpoint assignment graph} is
\begin{equation}
 D_{x,i}=\overline D_{x,i}[P_{x,i},Q_{x,i}].
 \label{eq:endpoints:five-graphs}
\end{equation}
Thus $D_{x,1},D_{x,2}$ supply ordinary spokes at incoming tails;
$D_{x,3}$ supplies marked spokes at outgoing auxiliary heads; and
$D_{x,4},D_{x,5}$ supply ordinary spokes there.
Define the enlarged neighbourhoods by
\begin{equation}
\begin{aligned}
 \mathcal N_{x,i}(a')&=N_{\overline D_{x,i}}(a')\cap Q_{x,i}
                               &&(a'\in\overline P_{x,i}),\\
 \mathcal M_{x,i}(u)&=N_{\overline D_{x,i}}(u)\cap P_{x,i}
                               &&(u\in B).
\end{aligned}
\label{eq:endpoints:enlarged-neighbourhoods}
\end{equation}
On the actual parts these are the neighbourhoods in $D_{x,i}$.
The first formula also includes absent arc indices, and the second
does not require $xu$ to be a spoke of either type.
For $a'\in\overline P_{x,i}$ put
\begin{equation}
 \mathcal E_{x,i}(a')=\{a''\in\overline P_{x,i}\setminus\{a'\}:
       \operatorname{dist}_\pi(\ell_{x,i}(a'),\ell_{x,i}(a''))\le3d\}.
\label{eq:endpoints:exceptional-partners}
\end{equation}
\end{definition}

\begin{lemma}[Perfect matchings from degree and cut bounds]
\label{lem:pairing:degree-cut-hall}
Let $X,Y$ be disjoint finite sets with $|X|=|Y|$, let $s>0$ and
$0<\epsilon<\lambda$, and let $B$ be a bipartite graph on $(X,Y)$.
Suppose every vertex has degree at least $\lambda s$, and
$e_B(P,Q)>0$ whenever $P\subseteq X$, $Q\subseteq Y$ and
$|P|,|Q|\ge\epsilon s$. Then
\begin{equation}
 B\text{ has a perfect matching}.
 \label{eq:pairing:degree-cut-hall}
\end{equation}
\end{lemma}

\begin{lemma}[Cut estimates from common-neighbour bounds]
\label{lem:new:cuts-from-codegrees}
Let $m,n\in\mathbb Z_{\ge0}$, $p\in[0,1]$ and $\eta,b\ge0$.
Let $D$ be a bipartite graph on $(A,B)$, where $|A|=m$, $|B|=n$,
and $d_D(x)=(p\pm\eta)n$ for $x\in A$.
Suppose a graph $J$ on $A$, of maximum degree at most $b$, contains
every distinct pair $x,x'$ with
$|N_D(x)\cap N_D(x')|>(p^2+\eta)n$.
Then, for all nonempty $P\subseteq A$ and $Q\subseteq B$,
\begin{equation}
 \bigl|e_D(P,Q)-p|P||Q|\bigr|
 \le |P||Q|\left(\frac{3\eta n}{|Q|}
                  +\frac{(b+1)n}{|P||Q|}\right)^{1/2}.
 \label{eq:new:fresh-endpoint-candidacy:E1}
\end{equation}
\end{lemma}

\begin{definition}[Vortex]
\label{def:completion:vortex}
Fix $\beta,\varrho_*>0$, $0<\epsilon<1/4$ and $m_*\in\mathbb N$.
Let $P$ be a $D$-regular graph on $V$, where $|V|=n\ge1$ and
$D\ge n/2$, and let $U$ be disjoint from $V$ with
$\varrho=2|U|/D\in[\varrho_*,1]$.
A \emph{$(\beta,\epsilon,\varrho_*,m_*)$-vortex} for $(P,U)$ is a
pair of nested sequences
\[
 V=V_0\supseteq\cdots\supseteq V_\ell,\qquad
 U=U_0\supseteq\cdots\supseteq U_\ell
 \qquad(\ell\ge0).
\]
Writing $n_i=|V_i|$, $u_i=|U_i|$ and $D_i=2u_i/\varrho$, we require:
\begin{enumerate}[label=\textup{(V\arabic*)}]
\item\label{item:completion:vortex:sizes}
$n_{i+1}=\lfloor\epsilon n_i\rfloor$ for $0\le i<\ell$, and
$\epsilon m_*/2\le n_\ell<m_*$;
\item\label{item:completion:vortex:indices}
$u_{i+1}=\lfloor\epsilon u_i\rfloor$ for $0\le i<\ell$;
\item\label{item:completion:vortex:degrees}
for $1\le i\le\ell$ and $v\in V_{\max\{0,i-2\}}$,
\begin{equation}
 \left|D_i-\frac Dn n_i\right|\le\beta n_i,\qquad
 \left|d_P(v;V_i)-D_i\right|\le\beta n_i.
 \label{eq:family:real-centres}
\end{equation}
\end{enumerate}
\end{definition}

\begin{lemma}[A permutation preserving nested sets]
\label{lem:writing:shell-permutation}
Let $h\ge1$ and $t\ge0$ be integers, and let
$V=V_0\supseteq V_1\supseteq\cdots\supseteq V_t$ be finite sets.
Suppose every nonempty $V_i\setminus V_{i+1}$ and the terminal set
$V_t$ have at least $h$ elements. Then there is a permutation $\pi$ of
$V$, all of whose cycles have length at least $h$, such that
\begin{equation}
 \pi(V_i)=V_i\quad(0\le i\le t).
 \label{eq:completion:shell-permutation}
\end{equation}
Every $V_i\setminus V_j$, $i<j$, is preserved by $\pi$. Moreover, if
$1\le d<h$, every interval
$\{x,\pi(x),\ldots,\pi^{d-1}(x)\}$ lies in one shell
$V_i\setminus V_{i+1}$ or in $V_t$.
\end{lemma}

\begin{definition}[Ordinary completion estimates]
\label{def:completion:ordinary-estimates}
Fix integers $r\ge3$, $d\ge2$, $k\ge r+2$, $0<\varrho\le1$, $0<s\le1/100$,
positive $\alpha,\epsilon$ and $0<\omega_{\rm est}\le1/8$.
Let $\mathcal R=(V,U,R_{\mathcal R},H_{\mathcal R})$ be an ordinary
completion host on $(P,V,U,\pi)$, and fix an orientation of
$P-E(F_{\pi,3d})$. The cycle weightings $\lambda_A$, the endpoint
matchings $\lambda_{A,x}$ when $r=3$, and the wheel weighting $w_0$
specified below are fixed on their respective domains when $\mathcal R$ varies.
Let $\delta_{\rm deg},\eta_{\rm bal},\delta_{\rm bal},\varepsilon_*>0$
and $\mu>0$.
The degree tolerance $\delta_{\rm deg}$ concerns $P$.
The tolerances $\eta_{\rm bal}$ and $\delta_{\rm bal}$ concern
restricted degree differences in $\mathcal R$, at vertices of $V$ and
at vertices of $I$, respectively. The neighbourhood and load
error is $\varepsilon_*$. We say that $\mathcal R$ has
\emph{ordinary completion estimates} with parameters
$(\delta_{\rm deg},\eta_{\rm bal},\delta_{\rm bal},\varepsilon_*;\mu)$
if the following conditions hold.
When $\mu$ is omitted, it is understood to be $1$.
The displayed inequalities below also use $\mu=1$ in subsequent
references unless a different value is specified.
\begin{enumerate}[label=\textup{(O\arabic*)}]
\item\label{item:completion:ordinary:geometry}
\emph{Geometry and degrees in $P$.} Assume
\begin{equation}
 \omega_{\rm est} N\le M\le N,\quad \epsilon N/2\le m\le\epsilon N,\quad
 \omega_{\rm est} m\le|J|\le m,\quad |T|+|W|\le2\epsilon m,
 \quad \pi(I)=I,\quad\pi(T)=T,
 \label{eq:protected:geometry:ordinary}
\end{equation}
\begin{equation}
\begin{gathered}
 |d_P(v)-2M/\varrho|\le\delta_{\rm deg} N/4,\quad
 |d_P(v;I)-2|J|/\varrho|\le\delta_{\rm deg} m/4,\quad
 |d_P(v;T)-2|W|/\varrho|\le\delta_{\rm deg} m/4,\\
 d_P(v)\ge(\delta_{C_r}+10\alpha)N,\quad
 d_P(v;I)\ge(\delta_{C_r}+10\alpha)m\qquad(v\in V).
\end{gathered}
\label{eq:family:protected-profiles:ordinary}
\end{equation}

\item\label{item:completion:ordinary:reference}
\emph{Restricted balance.} Use the differences in
\eqref{eq:completion:ordinary-differences}. Assume
\begin{equation}
\begin{aligned}
 \max\{|b_{\mathcal R}^{I,J}(v)|,|b_{\mathcal R}^{T,W}(v)|\}
 &\le\eta_{\rm bal}m &&(v\in V),\\
 \max\{|b_{\mathcal R}^{I,J}(v)|,|b_{\mathcal R}^{T,W}(v)|\}
 &\le\delta_{\rm bal}m &&(v\in I).
\end{aligned}
\label{eq:protected:ordinary-reference-errors}
\end{equation}
The smaller second bound permits correction inside $(I,J)$.
Both bounds on $(T,W)$ are measured at $m$, not at $|T|$.

\item\label{item:completion:ordinary:local}
\emph{Local cycle estimates.} The graph $\mathcal R$ has ordinary
local cycle estimates on $(A,B;X,Y)=(V,U;V,U)$ and
$(I',J';V',U')$, using
$F=F_{\pi,3d}$ and $P_{\rm el}=P-E(F)$, with
$D_A=2|B|/\varrho$, $q=\varrho s$, error $\varepsilon_*$ and
coefficient bounds $\omega_{\rm est},\omega_{\rm est}^{-1}$.

\item\label{item:completion:ordinary:potential}
\emph{Potential wheel estimates.} Let $\mathcal W_{P[V']}$ consist
of the ordinary $r$-wheels with hubs in $U'$, rim edges in $P[V']$
and $(3d,\pi)$-separated rim labels. Fix
$w_0:\mathcal W_{P[V']}\to\mathbb R_{>0}$.
Use the potential sums
\eqref{eq:loads:ordinary-potential-seed}--\eqref{eq:loads:ordinary-potential-transfers}
with $P[V']$, $F_{\pi,3d}[V']$, the fixed integer $k$ and normalization $n'$.
Assume
\begin{equation}
\begin{gathered}
 d_{H_{\mathcal R}}(v;U')\ge4\mu\omega_{\rm est} n'\quad(v\in V'),\qquad
 \omega_{\rm est}(n')^{1-r}\le w_0(W)\le \omega_{\rm est}^{-1}(n')^{1-r}\quad(W\in\mathcal W_{P[V']}),\\
 |\widehat L_e(\mathcal R[V'\cup U'])-1|\le\varepsilon_*
 \quad(e\text{ a potential rim edge in $P[V']^{\rm adm}$ or spoke}),\\
 \widehat I_e(\mathcal R[V'\cup U'])\ge4\mu\omega_{\rm est}
 \quad(e\in E(P[V']^{\rm adm})),\qquad
 \widehat T_{v,u,u'}(\mathcal R[V'\cup U'])\ge4\mu\omega_{\rm est}
 \quad(v\in V',\ u\ne u'\in U').
\end{gathered}
\label{eq:protected:ordinary-full-data}
\end{equation}

\item\label{item:completion:ordinary:cuts}
\emph{Packing and inner correction cuts.} Let $R^\to[A]$
be the tail--head incidence graph of the fixed orientation restricted to
$R_{\mathcal R}[A]$. The ordinary cut conditions are the following
instances of \eqref{eq:cuts:large}:
\begin{equation}
\begin{array}{c|c|c}
 \text{graphs}&\text{parts}&\text{parameters}\\\hline
 H_{\mathcal R}[V',U'],\ R^\to[V']&(V',U'),\ ((V')^+,(V')^-)&(\omega_{\rm est},4\mu \omega_{\rm est})\\
 H_{\mathcal R}[I,J],\ R^\to[I]&(I,J),\ (I^+,I^-)&(\omega_{\rm est},2\mu \omega_{\rm est})
\end{array}
\label{eq:protected:ordinary-cut-data}
\end{equation}
These cuts are assumed on the displayed parts before forbidding
the induced graph on $T,W$.
\end{enumerate}
The parameter $\mu$ multiplies only the count and cut lower bounds in
\ref{item:completion:ordinary:potential} and \ref{item:completion:ordinary:cuts}.
The coefficient bounds, load targets, degree conditions on $P$ and
cut thresholds are independent of $\mu$.
\end{definition}

\begin{lemma}[Ordinary cover-down with a protected inner pair]
\label{lem:completion:ordinary-cover-down}
Fix an integer $r\ge3$ and $\alpha>0$. Let $k\ge r+2$ be an integer
with $1/k\ll\alpha,1/r$. Fix $0<\varrho\le1$, $0<s\le1/100$,
$\epsilon_{\max}>0$ and $0<\omega_{\rm est}\le1/8$.
Let $\epsilon\le\epsilon_{\max}$ and
\begin{equation}
\begin{aligned}
 0<\delta_{\rm bal}&\ll\sigma\ll\eta_{\rm bal}\ll\gamma
 \ll\epsilon\ll\delta_{\rm deg},\varepsilon_*\\
 &\ll\alpha,\varrho,s,\omega_{\rm est},1/k,1/r,\epsilon_{\max}.
\end{aligned}
 \label{eq:completion:cover-hierarchy:ordinary}
\end{equation}
For every integer $d\ge2$, the following holds when
$0<1/N\ll1/d,\delta_{\rm bal}$.
Let $\mathcal R$ be an $r$-wheel-divisible ordinary completion host
on $(P,V,U,\pi)$, with $T\subseteq I\subseteq V$ and
$W\subseteq J\subseteq U$. Assume that $\mathcal R$ has ordinary
completion estimates with parameters
$(\delta_{\rm deg},\eta_{\rm bal},\delta_{\rm bal},\varepsilon_*;1)$,
relative to the fixed cycle weightings, the endpoint matchings when
$r=3$, the wheel weighting, and a fixed orientation of the eligible edges of $P$.
Put $m=|I|$.
Then there is a packing $\mathcal P\subseteq\mathcal W(\mathcal R)$
whose remainder
$\mathcal R'=\mathcal R-\bigcup_{W'\in\mathcal P}E(W')$,
regarded as an extended graph on $(I,J)$,
is $r$-wheel-divisible, is an extended subgraph of $\mathcal R[I\cup J]$, and satisfies
\begin{equation}
\begin{gathered}
 \Delta_*(\mathcal R[I\cup J]-\mathcal R')\le\gamma m,\qquad
 \Delta_*((\mathcal R[I\cup J]-\mathcal R')\cap\operatorname{star}(T,W))
 \le\sigma m,\\
 \mathcal R'[T\cup W]=\mathcal R[T\cup W].
\end{gathered}
\label{eq:family:protected-output:ordinary}
\end{equation}
The case $T=W=\varnothing$ is included.
\end{lemma}

\begin{localclaim}[A divisible inner graph]\label{clm:protected:inner:ordinary}\label{step:protected:inner:ordinary}
There is an extended subgraph
$D\subseteq\mathcal C$ with $D[T\cup W]=\varnothing$ and
$\Delta_*(D)\le C\xi m$ such that $\mathcal C-D$ is $r$-wheel-divisible.
\end{localclaim}

\begin{localclaim}[Covering the edges at the deeper pair]\label{clm:protected:deep:ordinary}\label{step:protected:deep:ordinary}
There are edge-disjoint wheel packings $\mathcal P_E,\mathcal P_D$
in $\mathcal Q$ such that, writing
$F_E=\bigcup_{W'\in\mathcal P_E}W'$ and
$F_D=\bigcup_{W'\in\mathcal P_D}W'$, we have
\[
 E(F_E)\cap E(\mathcal Q[I\cup J])=E_0,\qquad
 |E(W')\cap E_0|=1\quad(W'\in\mathcal P_E),\qquad
 \Delta_*(F_E)\le C_E\sqrt\xi N.
\]
Write $\mathcal Q_0=\mathcal Q-F_E$. Then
\begin{equation}
\begin{gathered}
 E(\mathcal Q_0)\cap\operatorname{star}(T,W)\subseteq E(F_D),\quad
 E(F_D)\cap\operatorname{star}(I\setminus T,J\setminus W)=\varnothing,\\
 \max_{z\in X\cup Z}\max\{d_{\rm aux}(z;F_D),d_{\rm phys}(z;F_D)\}
 \le C_D(|T|+|W|).
\end{gathered}
\label{eq:completion:deep-output:ordinary}
\end{equation}
For every $W'\in\mathcal P_D$,
\[
 |V(W')\cap(T\cup W)|=1,\qquad
 V(W')\setminus(T\cup W)\subseteq X\cup Z.
\]
\end{localclaim}

\begin{localclaim}[Covering the edges outside the active inner pair]\label{clm:protected:active:ordinary}\label{step:protected:active:ordinary}
There is a wheel packing in $\mathcal Q'$ with union $F_U$ such that
\begin{equation}
 E(\mathcal Q')\setminus E(\mathcal Q'[I'\cup J'])\subseteq E(F_U),
 \qquad \Delta_*(F_U[I'\cup J'])\le\nu N.
 \label{eq:completion:active-output:ordinary}
\end{equation}
\end{localclaim}

\begin{localclaim}[The next divisible remainder]\label{clm:protected:restore:ordinary}\label{step:protected:restore:ordinary}
The remainder $\mathcal R'=\mathcal R-F_E-F_D-F_U$ is $r$-wheel-divisible,
is an extended subgraph of $\mathcal R[I\cup J]$, and satisfies
\eqref{eq:family:protected-output:ordinary}. In fact,
\begin{equation}
 E(\mathcal R[I\cup J]-\mathcal R')
 =E_0\dot\cup E(F_U[I'\cup J']).
 \label{eq:completion:one-level-remainder:ordinary}
\end{equation}
\end{localclaim}

\begin{definition}[Marked completion estimates]
\label{def:completion:marked-estimates}
Fix an even integer $c\ge8$, an integer $d\ge2$, $0<\varrho\le1$, $0<s\le1/100$, positive $\alpha,\epsilon$, and
$0<\omega_{\rm est}\le1/8$. Put
\[
 p=\varrho s/2,\qquad \alpha_c=\alpha/4,\qquad
 \delta_c=\min\{\alpha/64,p/128\},\qquad h_c=\alpha p/64.
\]
Let $\mathcal R=(R^0_{\mathcal R},R^K_{\mathcal R},H^0_{\mathcal R},H^K_{\mathcal R})$
be a marked completion host on $(P,V,U,\pi)$.
The cycle functions $\omega_A$ and the wheel weighting
$w_0$ specified below are fixed on their respective domains when
$\mathcal R$ varies. Let
$\delta_{\rm deg},\eta_{\rm bal},\delta_{\rm bal},\varepsilon_*>0$
and $\mu>0$.
The degree tolerance $\delta_{\rm deg}$ concerns $P$.
The tolerances $\eta_{\rm bal}$ and $\delta_{\rm bal}$ concern
restricted degree differences in $\mathcal R$, at all roots and
at roots in $I\cup J$, respectively. The neighbourhood and load
error is $\varepsilon_*$. We say that $\mathcal R$ has
\emph{marked completion estimates} with parameters
$(\delta_{\rm deg},\eta_{\rm bal},\delta_{\rm bal},\varepsilon_*;\mu)$
if the following conditions hold.
When $\mu$ is omitted, it is understood to be $1$.
The displayed inequalities below also use $\mu=1$ in subsequent
references unless a different value is specified.
\begin{enumerate}[label=\textup{(M\arabic*)}]
\item\label{item:completion:marked:geometry}
\emph{Geometry and degrees in $P$.} Assume
\begin{equation}
 \omega_{\rm est} N\le M\le N,\quad \epsilon N/2\le m\le\epsilon N,\quad
 \omega_{\rm est} m\le|J|\le m,\quad |T|+|W|\le2\epsilon m,
 \quad \pi(I)=I,\quad\pi(T)=T,
 \label{eq:protected:geometry:marked}
\end{equation}
\begin{equation}
\begin{gathered}
 |d_P(v)-2M/\varrho|\le\delta_{\rm deg} N/4,\quad
 |d_P(v;I)-2|J|/\varrho|\le\delta_{\rm deg} m/4,\quad
 |d_P(v;T)-2|W|/\varrho|\le\delta_{\rm deg} m/4,\\
 d_P(v)\ge(1/2+10\alpha)N,\quad
 d_P(v;I)\ge(1/2+10\alpha)m\qquad(v\in V).
\end{gathered}
\label{eq:family:protected-profiles:marked}
\end{equation}

\item\label{item:completion:marked:reference}
\emph{Restricted balance.} For the differences in
\eqref{eq:completion:marked-differences}, write
\[
 \|\mathbf a_{\mathcal R}^{A,B}\|_{X,Y}
 =\max\{\max_{v\in X,\,j\in\{+,-,K\}}|a_{\mathcal R}^{j,A,B}(v)|,
          \max_{u\in Y}|a_{\mathcal R}^{U,A}(u)|\}.
\]
Assume
\begin{equation}
\begin{aligned}
 \max\{\|\mathbf a_{\mathcal R}^{I,J}\|_{V,U},
         \|\mathbf a_{\mathcal R}^{T,W}\|_{V,U}\}
 &\le\eta_{\rm bal}m,\\
 \max\{\|\mathbf a_{\mathcal R}^{I,J}\|_{I,J},
         \|\mathbf a_{\mathcal R}^{T,W}\|_{I,J}\}
 &\le\delta_{\rm bal}m.
\end{aligned}
\label{eq:protected:marked-reference-errors}
\end{equation}
The smaller second bound permits correction inside $(I,J)$.
Both bounds on $(T,W)$ are measured at $m$, not at $|T|$.

\item\label{item:completion:marked:local}
\emph{Local cycle estimates.} The graph $\mathcal R$ has marked
local cycle estimates on $(A,B;X,Y)=(V,U;V,U)$ and
$(I',J';V',U')$,
with $s_0=s$, $s_K=t=s/(c-1)$,
$p=\varrho s/2$, $k=\varrho t/2$, error $\varepsilon_*$,
structural bound $\omega_{\rm est}$ and count multiplier $\mu$.

\item\label{item:completion:marked:potential}
\emph{Potential wheel estimates.} Put $D'=2|U'|/\varrho$.
Fix positive coefficients $w_0(W(C,u))$ for $u\in U'$ and
$C\in\mathcal C_P^{V'}$, defined by
\eqref{eq:completion:parent-marked-cycles} with $A=V'$, with
\[
 w_0(W(C,u))=w_0(W(C,u'))\qquad(u,u'\in U').
\]
Thus the coefficient of a potential wheel depends only on its typed rim cycle.
The following bounds concern the packing pair $(V',U')$.
\begin{subequations}\label{eq:protected:marked-full-data}
For $v\in V'$ and distinct $x,y\in V'$,
\begin{equation}
\begin{gathered}
 |d^\pm_{R^0_{\mathcal R}}(v;V')-pD'|\le\varepsilon_*n',\qquad
 |d^\pm_{R^K_{\mathcal R}}(v;V')-pD'/(c-1)|\le\varepsilon_*n',\\
 |N^+_{R^0_{\mathcal R}}(x;V')\cap N^-_{R^0_{\mathcal R}}(y;V')|
 \ge8\mu\alpha_cp^2n'.
 \label{eq:protected:marked-rim-data}
\end{gathered}
\end{equation}
The potential compatible-hub and common-cycle counts satisfy
\begin{equation}
\begin{aligned}
 \widehat H_C&\ge8\mu\omega_{\rm est}n'
       &&(C\in\mathcal C_P^{V'}),\\
 |\mathcal C(u,u')|&\ge8\mu\omega_{\rm est}(n')^c
       &&(u\ne u'\in U'),\\
 |\mathcal F_j(v,v';u,u')|&\ge8\mu\omega_{\rm est}(n')^{c-1}
       &&(v\ne v'\in V',\ u\ne u'\in U',\ j\in\{0,K\}).
\end{aligned}
 \label{eq:protected:marked-extension-data}
\end{equation}
The first count requires only the prescribed spokes, irrespective
of whether the rim arcs are present. The path count omits all four
root spokes. Finally, assume
\begin{equation}
\begin{aligned}
 \omega_{\rm est}(n')^{1-c}\le w_0(W(C,u))
       &\le\omega_{\rm est}^{-1}(n')^{1-c}
       &&(C\in\mathcal C_P^{V'},\ u\in U'),\\
 |\widehat L_e-1|&\le\varepsilon_*
       &&(e\text{ a potential typed rim occurrence or spoke}).
\end{aligned}
 \label{eq:protected:marked-weight-data}
\end{equation}
The load inequality holds for every potential typed rim occurrence
or spoke $e$ on $(P[V'],V',U',\pi|_{V'})$, including absent roots,
with its indicator omitted as in \eqref{eq:loads:marked-potential-seed}.
\end{subequations}

\item\label{item:completion:marked:cuts}
\emph{Packing and inner correction cuts.} The graphs in the following
table are components of $\mathcal R$.
For $R^j[A]$ use its tail--head graph on $(A^+,A^-)$, and for
$H^j[A,B]$ use $(A,B)$. The marked cut assumptions are
\begin{equation}
\begin{array}{c|c|c}
 \text{graphs}&\text{restriction}&\text{parameters}\\\hline
 R^0,R^K,H^{0},H^{K}&(V',U')&(\omega_{\rm est},4\mu \omega_{\rm est})\\
 R^0,R^K,H^{0},H^{K}&(I,J)&(\omega_{\rm est},2\mu \omega_{\rm est})\\
 R^0&(V',U')&(\delta_c,8\mu h_c)
\end{array}
\label{eq:protected:marked-cut-data}
\end{equation}
The middle column specifies the restrictions to the displayed parts.
In the last row, $D_{R^0[V']}$ satisfies
\eqref{eq:capacity:large-cut} at order $|V'|$, with the parameters
from \eqref{eq:capacity:cuts} at $\alpha_c,p$ and with $h_c$ replaced
by $8\mu h_c$. The other two rows impose \eqref{eq:cuts:large} on all
four displayed incidence graphs. All parameter pairs are positive,
and their first coordinates are less than $1/4$.
\end{enumerate}
The parameter $\mu$ multiplies only the count and cut lower bounds in
\ref{item:completion:marked:local}--\ref{item:completion:marked:cuts}.
The coefficient bounds, load targets, degree conditions on $P$ and
cut thresholds are independent of $\mu$.
\end{definition}

\begin{localclaim}[A divisible inner graph]\label{clm:protected:inner:marked}\label{step:protected:inner:marked}
There is an extended subgraph
$D\subseteq\mathcal C$ with $D[T\cup W]=\varnothing$ and
$\Delta_*(D)\le C\xi m$ such that $\mathcal C-D$ is marked $c$-wheel-divisible.
\end{localclaim}

\begin{localclaim}[Covering the edges at the deeper pair]\label{clm:protected:deep:marked}\label{step:protected:deep:marked}
There are edge-disjoint wheel packings $\mathcal P_E,\mathcal P_D$
in $\mathcal Q$ such that, writing
$F_E=\bigcup_{W'\in\mathcal P_E}W'$ and
$F_D=\bigcup_{W'\in\mathcal P_D}W'$, we have
\[
 E(F_E)\cap E(\mathcal Q[I\cup J])=E_0,\qquad
 |E(W')\cap E_0|=1\quad(W'\in\mathcal P_E),\qquad
 \Delta_*(F_E)\le C_E\sqrt\xi N.
\]
Write $\mathcal Q_0=\mathcal Q-F_E$. Then
\begin{equation}
\begin{gathered}
 E(\mathcal Q_0)\cap\operatorname{star}(T,W)\subseteq E(F_D),\quad
 E(F_D)\cap\operatorname{star}(I\setminus T,J\setminus W)=\varnothing,\\
 \max_{z\in X\cup Z}\max\{d_{\rm aux}(z;F_D),d_{\rm phys}(z;F_D)\}
 \le C_D(|T|+|W|).
\end{gathered}
\label{eq:completion:deep-output:marked}
\end{equation}
For every $W'\in\mathcal P_D$,
\[
 |V(W')\cap(T\cup W)|=1,\qquad
 V(W')\setminus(T\cup W)\subseteq X\cup Z.
\]
\end{localclaim}

\begin{localclaim}[Covering the edges outside the active inner pair]\label{clm:protected:active:marked}\label{step:protected:active:marked}
There is a wheel packing in $\mathcal Q'$ with union $F_U$ such that
\begin{equation}
 E(\mathcal Q')\setminus E(\mathcal Q'[I'\cup J'])\subseteq E(F_U),
 \qquad \Delta_*(F_U[I'\cup J'])\le\nu N.
 \label{eq:completion:active-output:marked}
\end{equation}
\end{localclaim}

\begin{localclaim}[The next divisible remainder]\label{clm:protected:restore:marked}\label{step:protected:restore:marked}
The remainder $\mathcal R'=\mathcal R-F_E-F_D-F_U$ is marked $c$-wheel-divisible,
is an extended subgraph of $\mathcal R[I\cup J]$, and satisfies
\eqref{eq:family:protected-output:marked}. In fact,
\begin{equation}
 E(\mathcal R[I\cup J]-\mathcal R')
 =E_0\dot\cup E(F_U[I'\cup J']).
 \label{eq:completion:one-level-remainder:marked}
\end{equation}
\end{localclaim}

\begin{lemma}[Ordinary full-host sampling estimates]
\label{lem:completion:ordinary-reference}
Let $r\ge3$, $\vartheta\ge\max\{1/2,\delta_{C_r}\}$, and
$\alpha,\omega_*,p_*>0$ be fixed.

There are an integer $k\ge r+2$ and $\beta,b_-,b_+>0$, depending only
on $r,\vartheta,\alpha,\omega_*,p_*$, with the following property.
Let $0<\eta_*\le1$ and
\[
 0<\varepsilon_0\ll\eta_*,1/r,\vartheta,\alpha,
 \omega_*,p_*,1/k,\beta,b_-,1/b_+,1.
\]
For every integer $d\ge2$, there is $n_0$ such that the following
holds for $n\ge n_0$. Let $P$ be a graph on $V$, let $U$ be disjoint
from $V$, and put $|V|=n$, $|U|=m$.
Let $(R_0,H_0)$ be an ordinary completion sample on $(P,V,U,\pi)$
with parameters $\varrho,s,d,(a_u),(b_u)$.
Put $\mathcal F=F_{\pi,3d}$, $P^{\rm adm}=P-E(\mathcal F)$,
$p_R=\varrho s$, $p_H=s$, and assume
\begin{equation}
 \omega_*n\le m\le n,\quad p_R,p_H\in[p_*,1],\quad n/2\le D_0\le2n,
 \label{eq:family:OF.A1}
\end{equation}
\begin{equation}
 p_RD_0=2mp_H,\label{eq:family:OF.A2}
\end{equation}
\begin{equation}
 \delta(P)\ge(\vartheta+\alpha)n,\quad
 |d_P(v)-D_0|\le\varepsilon_0n\quad(v\in V).
 \label{eq:family:OF.A3}
\end{equation}
Use the fixed cycle weighting $\lambda$ on $\mathcal C_r(P)$ and
wheel weighting $\omega_0$ on $\mathcal W_P$ in
\eqref{eq:family:OF.A11}--\eqref{eq:family:OF.A12}.
Then $b_-n^{1-r}\le\omega_0(W)\le b_+n^{1-r}$ for every
$W\in\mathcal W_P$.

With probability at least $1-n^{-10}$, putting $(Q,H)=(R_0,H_0)$,
we have $d_H(v)\ge\beta n$ for every $v\in V$ and
\begin{equation}
\begin{aligned}
 |\widehat L_e(Q,H;\omega_0)-1|&\le\eta_*
             &&(e\in E(P^{\rm adm})\dot\cup(V\times U)),\\
 \widehat I_{xy}(Q,H)&\ge\beta &&(xy\in E(P^{\rm adm})),\\
 \widehat T_{v,u,u'}(Q,H)&\ge\beta &&(v\in V,\ u,u'\in U,\ u\ne u').
\end{aligned}
 \label{eq:reference:ordinary-potential-output}
\end{equation}
Here the three functions are defined in
\eqref{eq:loads:ordinary-potential-seed}--\eqref{eq:loads:ordinary-potential-transfers},
with the fixed coefficient function $\omega_0$ in the first one.
\end{lemma}

\begin{localclaim}\label{clm:completion:raw:marked}\label{step:completion:raw:marked}
\[
 \Pr\left(\left(\bigcap_{i=0}^{\ell-1}\mathcal E_i^+\right)^c\right)\le\chi,
 \qquad \Pr(\mathcal E_{\rm amb,raw}^{\,c})\le n^{-15}.
\]
\end{localclaim}

\begin{localclaim}[Every permitted remainder]
\label{clm:completion:permitted-remainders:marked}
On $\mathcal E_{\rm chain}$, every physically injective,
marked $c$-wheel-divisible completion host $\mathcal R$ on
$(P,V,U,\pi)$ satisfying \eqref{item:completion:perturbation:marked}
with the fixed absorber $\mathcal A$ has a marked $c$-wheel decomposition.
\end{localclaim}

\begin{definition}[Extending lists]
\label{def:lists:extending}
Let $D$ be an oriented graph on $V$, $|V|=n$, and let $\lambda\ge0$.
A set $L\subseteq V$ is \emph{$\lambda$-extending in $D$} if
\begin{align}
 |L|&\ge\lambda n,\label{eq:new:prescribed-list}\\
 |N_D^+(x)\cap L|,\ |N_D^-(x)\cap L|&\ge\lambda n
                    \quad(x\in V),\label{eq:new:prescribed-one}\\
 |N_D^+(x)\cap N_D^-(y)\cap L|&\ge\lambda n
                    \quad(x\ne y\in V).\label{eq:new:prescribed-two}
\end{align}
\end{definition}

\begin{localclaim}\label{clm:ordinary:event}\label{step:ordinary:event}
There is an event $\mathcal E_{\rm ord}\subseteq\mathcal E_{\rm comp}$
on which the following conclusions hold simultaneously.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The raw loads, ordinary totals and weighted codegrees satisfy
\[
 |Z_{e,a}-1|\le\eta_{\rm app}\quad((e,a)\in\mathcal R_{\rm app}^+),\qquad
 d_\Omega^{\mathcal H}(e,f)\le K_{\rm cd}/n\quad(e\ne f\in V(\mathcal H)),
\]
\[
 \left|T_{r,w}-(1-\theta)f'_{r,w}n/r\right|\le\eta_{\rm app}n
 \quad(r\in\mathcal R_w,\ w\in U).
\]
\item The interval counts satisfy
\begin{equation}
 \bigl||Y_w|-a_wn\bigr|\le n^{3/4},\qquad
 |m_w-a_wn/d|\le n^{3/4}/d\quad(w\in U),
 \label{eq:family:OH.6.1}
\end{equation}
For $w\in U$ put $E_w^{\rm end}=\{a(I),I^+:I\in\mathcal X_w^2\}$.
\begin{equation}
 |\{w\in U:v\in E_w^{\rm end}\}|\le2n/d\quad(v\in V).
 \label{eq:family:OH.6.2}
\end{equation}
The unassigned counts in \eqref{eq:preparation:ord-unassigned-counts}
hold as well.
\item Each raw list $O_w$ is $\beta_{\rm raw}$-extending in $D_1^0$. For all distinct $x,y\in V$,
\begin{equation}
 |N_{H_1^0}(x)\cap N_{H_1^0}(y)|\ge a_0n.
 \label{eq:family:ordinary-common-index}
\end{equation}
\end{enumerate}
Moreover,
\begin{equation}
 \Pr(\mathcal E_{\rm ord})\ge1-\chi-n^{-10}.
 \label{eq:preparation:ordinary-joint-event}
\end{equation}
\end{localclaim}

\begin{localclaim}\label{clm:ordinary:packing}
There exist such a packing $\mathcal P$, reserved paths and assignments
$\theta_{2,w},\kappa_w$, and joint injections $\Psi_w$ satisfying
the path-extension and component-disjointness conditions of
Lemma~\ref{lem:images:residual-structure} and the image conclusions of
Lemma~\ref{lem:images:residual-prescriptions}, with the following bounds.
\begin{equation}
 |ra_{r,w}-(1-\theta)f'_{r,w}n|\le\lambda f'_{r,w}n
       \quad(w\in U,\ r\in\mathcal R_w),
 \label{eq:family:OH.8.2}
\end{equation}
\begin{equation}
 \Delta(G_{\rm rem})\le\lambda n,
 \label{eq:family:OH.8.3}
\end{equation}
\begin{equation}
 \Delta(H_{\rm rem}^K)\le\lambda n/4,\qquad
 b_w^{\rm miss}\le\lambda n/4\quad(w\in U),
 \label{eq:family:OH.8.4}
\end{equation}
and $\Delta(H_{\rm rem}^O)\le\lambda n$.
Moreover,
\[
 E(Q_w[A_w^0])=\varnothing,\qquad \Psi_w(X_w)\cap O_w=\varnothing.
\]
Each component of
$Q_w$ is a directed path, an isolated vertex or a directed cycle
of length at least three, and
\begin{equation}
 \theta n/4\le |V(Q_w)|\le10\theta n,
 \label{eq:family:OH.8.9}
\end{equation}
\begin{equation}
 |\{w\in U:v\in\psi_w(A_w^0)\}|\le2n/d+2\lambda n\quad(v\in V).
 \label{eq:family:OH.8.10}
\end{equation}
\end{localclaim}

\begin{localclaim}\label{clm:ordinary:embedding}\label{step:ordinary:embed}
There are an orientation $\vec S$, matchings $M_w\subseteq\vec S$,
sets $A_w^0\subseteq A_w\subseteq V(Q_w)$, and embeddings
$\Phi_w:Q_w\to\vec S$ with the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item \emph{Compatible prescribed images.}
Each $\Phi_w$ extends $\psi_w$ on $A_w^0$, and
\[
 \Phi_w(A_w)=\psi_w(A_w^0)\dot\cup\partial M_w\dot\cup Z_w,
 \qquad E(\Phi_w(Q_w[A_w]))=E(M_w).
\]
The maps $\Phi_w$ and $\Psi_w$ of Claim~\ref{clm:ordinary:packing}
have common extensions $\widehat\Phi_w:F_w^\circ\to\vec S$, with
\[
 E_{\rm phys}(\widehat\Phi_w(F_w^\circ))\cap
 E_{\rm phys}(\widehat\Phi_{w'}(F_{w'}^\circ))=\varnothing
 \quad(w\ne w').
\]
\item \emph{Required edges, inner labels and absorber avoidance.}
\[
\begin{gathered}
 E(E_{\rm bad})=\mathop{\dot\bigcup}_{w\in U}E_{\rm phys}(M_w),
 \qquad M_w=\varnothing\quad(w\in J),\\
 E(E_{\rm bad})\subseteq\bigcup_w E_{\rm phys}(\Phi_w(Q_w)),\qquad
 Z_w^*\subseteq\Phi_w(V(Q_w))\quad(w\in J),\\
 E_{\rm phys}(\widehat\Phi_w(F_w^\circ))\cap E_R(\mathcal A)=\varnothing,
 \qquad \widehat\Phi_w(V(F_w^\circ))\cap N_{H_{\mathcal A}}(w)=\varnothing.
\end{gathered}
\]
\item \emph{Degree and free-image bounds.}
For $F_{\rm small}=(V,\bigcup_w E_{\rm phys}(\Phi_w(Q_w)))$,
\begin{equation}
 \Delta(F_{\rm small})\le5\sqrt{10\theta}\,n.
 \label{eq:family:OH.10.6}
\end{equation}
Moreover,
\begin{equation}
 |\{(w,x):w\in U,\ x\in V(Q_w)\setminus A_w,\ \Phi_w(x)=v\}|
 \le\sqrt{10\theta}\,n+1\quad(v\in V).
 \label{eq:family:OH.10.7}
\end{equation}
\end{enumerate}
\end{localclaim}

\begin{localclaim}\label{clm:ordinary:residual}\label{step:ordinary:complete}
The residual graph satisfies
\begin{equation}
 d_H(w)=r_*k_*\quad(w\in U),\qquad
 d_R(v)=2d_H(v)\quad(v\in V),
 \label{eq:family:OH.HP.7}
\end{equation}
\begin{equation}
 R\subseteq P^{\rm adm},\qquad \mathcal A\subseteq\mathcal R,
 \qquad\mathcal R[I\cup J]=\mathcal B[I\cup J].
 \label{eq:family:OH.HP.8}
\end{equation}
In particular, $\mathcal R$ is ordinary $r_*$-wheel-divisible. Moreover,
\[
 \Delta_*\bigl((\mathcal R-\mathcal A)\triangle\mathcal B\bigr)
       \le\zeta_{\rm rem}n.
\]
\end{localclaim}

\begin{localclaim}\label{clm:long:event}\label{step:long:event}
There is an event $\mathcal E_{\rm long}\subseteq\mathcal E_{\rm comp}$
on which all the following conclusions hold simultaneously.
\begin{enumerate}[label=\textup{(\roman*)}]
\item\label{item:orientation:raw} The raw orientation satisfies
\[
 |d_{D_{\rm raw}}^\pm(v)-\varrho D/2|\le n^{3/5}\quad(v\in V),
 \qquad |\{z:x\to z\to y\text{ in }D_{\rm raw}\}|
 \ge\beta_{\rm or}n\quad(x\ne y).
\]
The raw selected types also satisfy
\begin{equation}
 \left|d^-_{D_{\rm sel,raw}^K}(v)-mt\right|\le n^{3/4},\qquad
 \left|d^-_{D_{\rm sel,raw}^0}(v)-ms\right|\le n^{3/4}
 \quad(v\in V).
 \label{eq:preparation:long-selected-indegrees}
\end{equation}
\item The raw interval counts satisfy, for $g=1,2$,
\begin{equation}
 \bigl||\mathcal X_w^g|-q_g(w)n/d\bigr|\le n^{3/4}/d
 \quad(w\in U),
 \label{eq:profiles:long-interval-count}
\end{equation}
\begin{equation}
 |N_g(v)-\mu_g|\le n^{3/5}\quad(v\in V).
 \label{eq:profiles:long-start-count}
\end{equation}
Put $b_{\rm fin}=dt_1$ and let $F_{\rm trim}$ be the graph of pairs
whose raw and final states differ, using the same colour variables.
Then
\begin{equation}
 b_{\rm fin}=dt_1,\qquad |b_{\rm fin}-mt|\le dn^{3/5},
 \qquad \Delta(F_{\rm trim})\le n^{3/4}.
 \label{eq:family:final-marked-count}
\end{equation}
The unassigned counts in \eqref{eq:preparation:long-unassigned-counts}
also hold.
\item The raw potentials, ordinary totals and codegrees satisfy
\[
 |Z_{e,a}-1|\le\eta_{\rm app}\quad((e,a)\in\mathcal R_{\rm app}^+),\qquad
 d_\Omega^{\mathcal H}(e,f)\le K_{\rm cd}/n\quad(e\ne f\in V(\mathcal H)),
\]
\[
 |T_{r,w}-(1-\theta)f_{r,w}n/r|\le\eta_{\rm app}n
 \quad(w\in U,\ r\in\mathcal R_w).
\]
\item Each list $O_{1,w}$ is $\beta_{\rm raw}$-extending in $D_1^0$. For all distinct $x,y\in V$,
\begin{equation}
 |N_{H_1^0}(x)\cap N_{H_1^0}(y)|\ge\nu_0|U|\ge2a_En.
 \label{eq:family:long-common-index}
\end{equation}
\end{enumerate}
Moreover,
\begin{equation}
 \Pr(\mathcal E_{\rm long})\ge1-\chi-n^{-10}.
 \label{eq:preparation:long-joint-event}
\end{equation}
\end{localclaim}

\begin{localclaim}\label{clm:long:packing}
For the fixed $S$, there exist a balanced orientation $\widehat D$
satisfying \eqref{item:orientation:balanced} and a physical-edge-disjoint
approximate wheel packing $\mathcal P$ using its stored eligible arc states.
Let $a_{r,w}$ count the ordinary $r$-wheels at $w$. Then
\begin{equation}
 |ra_{r,w}-(1-\theta)f_{r,w}n|\le\lambda f_{r,w}n
 \quad(w\in U,\ r\in\mathcal R_w).
 \label{eq:family:long-component-counts}
\end{equation}
\[
 \Delta_{\rm aux}(L_R(\widehat D,\mathcal P)),\Delta_{\rm phys}(L_R(\widehat D,\mathcal P)),\Delta(L_O(\mathcal P))\le\lambda n.
\]
\begin{equation}
 \Delta(L_K(\mathcal P))\le\lambda n/4.
 \label{eq:family:long-missing-spokes}
\end{equation}

\end{localclaim}
